import { useState, useCallback, useRef } from 'react';
import { getChatHistory, type ChatMessage } from '@/lib/api';
import apiClient from '@/lib/api-client';

export function useChat(repositoryId?: string) {
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [loading, setLoading] = useState(false);
    const [streamingContent, setStreamingContent] = useState('');
    const [error, setError] = useState<string | null>(null);
    const abortControllerRef = useRef<AbortController | null>(null);

    const loadHistory = useCallback(async (repoId: string) => {
        setLoading(true);
        setError(null);
        try {
            const data = await getChatHistory(repoId);
            setMessages(data.messages);
        } catch (e: unknown) {
            const err = e as any;
            const msg = err?.response?.data?.detail || err?.message || 'Failed to load chat history';
            setError(msg);
        } finally {
            setLoading(false);
        }
    }, []);

    const sendMessage = useCallback(async (question: string) => {
        if (!repositoryId) return;

        // Reset state
        setError(null);
        setStreamingContent('');

        // Add user message to UI immediately
        const userMsg: ChatMessage = { role: 'user', content: question, timestamp: new Date().toISOString() };
        setMessages(prev => [...prev, userMsg]);

        setLoading(true);

        try {
            // Cancel any existing request
            if (abortControllerRef.current) {
                abortControllerRef.current.abort();
            }
            abortControllerRef.current = new AbortController();

            const response = await fetch(`${import.meta.env.VITE_API_URL || 'http://localhost:8000'}/api/v1/chat`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${localStorage.getItem('access_token')}`,
                },
                body: JSON.stringify({
                    repository_id: repositoryId,
                    question,
                    chat_history: messages.slice(-10), // Send last 10 messages for context
                }),
                signal: abortControllerRef.current.signal,
            });

            if (!response.ok) {
                const errData = await response.json().catch(() => ({}));
                throw new Error(errData.detail || 'Failed to send message');
            }

            const reader = response.body?.getReader();
            if (!reader) throw new Error('No reader available');

            const decoder = new TextDecoder();
            let accumulatedResponse = '';
            let streamError: string | null = null;

            outer: while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                const chunk = decoder.decode(value, { stream: true });
                const lines = chunk.split('\n');

                for (const line of lines) {
                    if (!line.startsWith('data: ')) continue;

                    const payload = line.slice(6).trim();
                    if (payload === '[DONE]') break outer;

                    let data: Record<string, unknown>;
                    try {
                        data = JSON.parse(payload);
                    } catch {
                        // Malformed chunk — skip silently
                        continue;
                    }

                    // Backend sent an explicit error — surface it immediately
                    if (data.error) {
                        streamError = String(data.error);
                        break outer;
                    }

                    if (data.content) {
                        accumulatedResponse += String(data.content);
                        setStreamingContent(accumulatedResponse);
                    }

                    if (data.done) {
                        // Stream finished — persist assistant message
                        setMessages(prev => [
                            ...prev,
                            { role: 'assistant', content: accumulatedResponse, timestamp: new Date().toISOString() }
                        ]);
                        setStreamingContent('');
                    }
                }
            }

            if (streamError) {
                // Remove the optimistic user message so the UI is clean
                setMessages(prev => prev.slice(0, -1));
                setError(streamError);
            }

        } catch (e: unknown) {
            const err = e as any;
            if (err.name === 'AbortError') return;
            // Remove the optimistic user message on hard failures too
            setMessages(prev => prev.slice(0, -1));
            const msg = err.message || 'Something went wrong. Please try again.';
            setError(msg);
        } finally {
            setLoading(false);
            abortControllerRef.current = null;
        }
    }, [repositoryId, messages]);

    const clearHistory = useCallback(() => {
        setMessages([]);
        setStreamingContent('');
        setError(null);
    }, []);

    return {
        messages,
        loading,
        streamingContent,
        error,
        loadHistory,
        sendMessage,
        clearHistory,
    };
}

import { useState, useCallback } from 'react';
import { getRepositoryPulls, reviewPullRequest, type PullRequest, type PRReviewResponse } from '@/lib/api';

export function usePullRequests(repositoryId?: string) {
    const [pulls, setPulls] = useState<PullRequest[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [reviewing, setReviewing] = useState<number | null>(null);
    const [reviewError, setReviewError] = useState<string | null>(null);

    const fetchPulls = useCallback(async (id?: string) => {
        const targetId = id || repositoryId;
        if (!targetId) return;

        setLoading(true);
        setError(null);
        try {
            const data = await getRepositoryPulls(targetId);
            setPulls(data.pulls);
        } catch (e: unknown) {
            const err = e as any;
            const msg = err?.response?.data?.detail || err?.message || 'Failed to fetch pull requests';
            setError(msg);
        } finally {
            setLoading(false);
        }
    }, [repositoryId]);

    const performReview = useCallback(async (pr: PullRequest): Promise<PRReviewResponse> => {
        if (!repositoryId) throw new Error("No repository selected");

        setReviewing(pr.number);
        setReviewError(null);
        try {
            const result = await reviewPullRequest({
                repository_id: repositoryId,
                pr_number: pr.number,
                pr_title: pr.title,
            });
            return result;
        } catch (e: unknown) {
            const err = e as any;
            const msg = err?.response?.data?.detail || err?.message || 'AI review failed. Please try again.';
            setReviewError(msg);
            throw err;
        } finally {
            setReviewing(null);
        }
    }, [repositoryId]);

    return {
        pulls,
        loading,
        error,
        reviewing,
        reviewError,
        fetchPulls,
        performReview,
    };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import {
    getRepositories,
    getGithubRepos,
    connectRepository,
    deleteRepository,
    indexRepository,
    getRepoStatus,
    type RepoResponse,
    type GitHubRepo,
} from '@/lib/api';
import { useOrganization } from '@/contexts/OrganizationContext';

const POLL_INTERVAL_MS = 3000;

interface UseRepositoriesReturn {
    /** Connected repos from the backend. */
    repos: RepoResponse[];
    /** True while the initial fetch is in progress. */
    loading: boolean;
    /** Error message if the initial fetch failed. */
    error: string | null;
    /** Re-fetch the list from backend. */
    refresh: () => Promise<void>;
    /** GitHub repos available for connection (loaded on demand). */
    githubRepos: GitHubRepo[];
    /** True while GitHub repos are loading. */
    githubLoading: boolean;
    /** Error from GitHub repos fetch. */
    githubError: string | null;
    /** Fetch GitHub repos (call when opening the connect modal). */
    loadGithubRepos: () => Promise<void>;
    /** Connect + start indexing a GitHub repo. Returns the new repo or throws. */
    connectAndIndex: (ghRepo: GitHubRepo) => Promise<RepoResponse>;
    /** Delete a connected repo by ID. */
    removeRepo: (id: string) => Promise<void>;
    /** Trigger re-indexing for an existing repo. */
    reindexRepo: (id: string) => Promise<void>;
}

export function useRepositories(): UseRepositoriesReturn {
    const { currentOrganization } = useOrganization();

    const [repos, setRepos] = useState<RepoResponse[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const [githubRepos, setGithubRepos] = useState<GitHubRepo[]>([]);
    const [githubLoading, setGithubLoading] = useState(false);
    const [githubError, setGithubError] = useState<string | null>(null);

    // Track repos currently being polled
    const pollingRef = useRef<Map<string, ReturnType<typeof setInterval>>>(new Map());

    // --- Polling logic -----------------------------------------------------------

    const stopPolling = useCallback((repoId: string) => {
        const interval = pollingRef.current.get(repoId);
        if (interval) {
            clearInterval(interval);
            pollingRef.current.delete(repoId);
        }
    }, []);

    const startPolling = useCallback(
        (repoId: string) => {
            // Don't double-poll
            if (pollingRef.current.has(repoId)) return;

            const interval = setInterval(async () => {
                try {
                    const status = await getRepoStatus(repoId);
                    setRepos((prev) =>
                        prev.map((r) =>
                            r.id === repoId
                                ? {
                                    ...r,
                                    indexed_status: status.indexed_status,
                                    indexing_progress: status.indexing_progress,
                                    indexing_error: status.indexing_error,
                                }
                                : r,
                        ),
                    );
                    // Stop polling once indexing is complete or errored
                    if (status.indexed_status || status.indexing_error) {
                        stopPolling(repoId);
                    }
                } catch {
                    // Silently fail — the user can refresh to recover
                    stopPolling(repoId);
                }
            }, POLL_INTERVAL_MS);

            pollingRef.current.set(repoId, interval);
        },
        [stopPolling],
    );

    // Cleanup all polls on unmount
    useEffect(() => {
        const polls = pollingRef.current;
        return () => {
            polls.forEach((interval) => clearInterval(interval));
            polls.clear();
        };
    }, []);

    // Auto-start polling for repos that are actively indexing
    useEffect(() => {
        repos.forEach((r) => {
            const isIndexing = !r.indexed_status && r.indexing_progress > 0 && !r.indexing_error;
            if (isIndexing) {
                startPolling(r.id);
            }
        });
    }, [repos, startPolling]);

    // --- Fetch connected repos ---------------------------------------------------

    const refresh = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const data = await getRepositories(currentOrganization?.id);
            setRepos(data.repositories);
        } catch (e: unknown) {
            const err = e as any;
            const msg = err?.response?.data?.detail || err?.message || 'Failed to load repositories';
            setError(msg);
        } finally {
            setLoading(false);
        }
    }, [currentOrganization?.id]);

    useEffect(() => {
        refresh();
    }, [refresh, currentOrganization?.id]);

    // --- GitHub repo list (on-demand) -------------------------------------------

    const loadGithubRepos = useCallback(async () => {
        setGithubLoading(true);
        setGithubError(null);
        try {
            const data = await getGithubRepos();
            setGithubRepos(data.repositories);
        } catch (e: unknown) {
            const err = e as any;
            const msg = err?.response?.data?.detail || err?.message || 'Failed to fetch GitHub repos';
            setGithubError(msg);
        } finally {
            setGithubLoading(false);
        }
    }, []);

    // --- Connect + Index ---------------------------------------------------------

    const connectAndIndex = useCallback(
        async (ghRepo: GitHubRepo): Promise<RepoResponse> => {
            const newRepo = await connectRepository({
                repo_name: ghRepo.repo_name,
                full_name: ghRepo.full_name,
                description: ghRepo.description,
                url: ghRepo.clone_url || ghRepo.url,
                stars: ghRepo.stars,
                language: ghRepo.language,
                org_id: currentOrganization?.id || null, // Associate with current org
            });

            // Add to local state immediately
            setRepos((prev) => [newRepo, ...prev]);

            // Kick off indexing (fire-and-forget — polling will pick it up)
            try {
                await indexRepository(newRepo.id);
                // Optimistically show progress starting
                setRepos((prev) =>
                    prev.map((r) =>
                        r.id === newRepo.id ? { ...r, indexing_progress: 1 } : r,
                    ),
                );
                startPolling(newRepo.id);
            } catch {
                // Indexing failed to start — repo is still saved, user can retry
            }

            return newRepo;
        },
        [startPolling, currentOrganization?.id],
    );

    // --- Delete ------------------------------------------------------------------

    const removeRepo = useCallback(async (id: string) => {
        await deleteRepository(id);
        stopPolling(id);
        setRepos((prev) => prev.filter((r) => r.id !== id));
    }, [stopPolling]);

    // --- Re-index ----------------------------------------------------------------

    const reindexRepo = useCallback(
        async (id: string) => {
            await indexRepository(id);
            setRepos((prev) =>
                prev.map((r) =>
                    r.id === id
                        ? { ...r, indexed_status: false, indexing_progress: 1, indexing_error: null }
                        : r,
                ),
            );
            startPolling(id);
        },
        [startPolling],
    );

    return {
        repos,
        loading,
        error,
        refresh,
        githubRepos,
        githubLoading,
        githubError,
        loadGithubRepos,
        connectAndIndex,
        removeRepo,
        reindexRepo,
    };
}

import { useState, useCallback } from 'react';
import { searchRepository, type SearchResult } from '@/lib/api';

export function useSearch(repositoryId?: string) {
    const [results, setResults] = useState<SearchResult[]>([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const performSearch = useCallback(async (query: string) => {
        if (!repositoryId || !query.trim()) return;

        setLoading(true);
        setError(null);
        try {
            const data = await searchRepository(repositoryId, query);
            setResults(data.results);
        } catch (e: unknown) {
            const err = e as any;
            const msg = err?.response?.data?.detail || err?.message || 'Failed to perform search';
            setError(msg);
        } finally {
            setLoading(false);
        }
    }, [repositoryId]);

    const clearResults = useCallback(() => {
        setResults([]);
        setError(null);
    }, []);

    return {
        results,
        loading,
        error,
        performSearch,
        clearResults,
    };
}

import { useState, useMemo, useEffect } from "react";
import { toast } from "sonner";
import {
  Search,
  RefreshCw,
  Trash2,
  Github,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Lock,
  Star,
  FolderGit2,
} from "lucide-react";
import { StatusBadge } from "@/components/shared/StatusBadge";
import { Button } from "@/components/ui/button";
import { useRepositories } from "@/hooks/useRepositories";
import type { RepoResponse, GitHubRepo } from "@/lib/api";

// ─── Helpers ────────────────────────────────────────────────────────────────────

function repoStatus(r: RepoResponse): "indexed" | "indexing" | "error" | "not_indexed" {
  if (r.indexing_error) return "error";
  if (r.indexed_status) return "indexed";
  if (r.indexing_progress > 0) return "indexing";
  return "not_indexed";
}

const statusConfig = {
  indexed: { label: "Indexed", variant: "success" as const, icon: CheckCircle2 },
  indexing: { label: "Indexing…", variant: "warning" as const, icon: Loader2 },
  error: { label: "Error", variant: "error" as const, icon: AlertCircle },
  not_indexed: { label: "Not Indexed", variant: "default" as const, icon: null },
};

function timeAgo(iso: string | null): string {
  if (!iso) return "—";
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60_000);
  if (mins < 1) return "Just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

// ─── Page ───────────────────────────────────────────────────────────────────────

export default function RepositoriesPage() {
  const {
    repos,
    loading,
    error,
    refresh,
    githubRepos,
    githubLoading,
    githubError,
    loadGithubRepos,
    connectAndIndex,
    removeRepo,
    reindexRepo,
  } = useRepositories();

  const [search, setSearch] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [ghSearch, setGhSearch] = useState("");
  const [connecting, setConnecting] = useState<string | null>(null); // full_name being connected
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [reindexingId, setReindexingId] = useState<string | null>(null);

  // Close modal on Escape key
  useEffect(() => {
    if (!showModal) return;
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setShowModal(false);
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [showModal]);

  const filtered = useMemo(
    () => repos.filter((r) => r.full_name.toLowerCase().includes(search.toLowerCase())),
    [repos, search],
  );

  // GitHub repos filtered by search AND not already connected
  const connectedNames = useMemo(() => new Set(repos.map((r) => r.full_name)), [repos]);
  const filteredGhRepos = useMemo(
    () =>
      githubRepos
        .filter((r) => r.full_name.toLowerCase().includes(ghSearch.toLowerCase()))
        .filter((r) => !connectedNames.has(r.full_name)),
    [githubRepos, ghSearch, connectedNames],
  );

  // ─── Handlers ────────────────────────────────────────────────────────────────

  const handleOpenModal = () => {
    setShowModal(true);
    setGhSearch("");
    loadGithubRepos();
  };

  const handleConnect = async (ghRepo: GitHubRepo) => {
    setConnecting(ghRepo.full_name);
    try {
      await connectAndIndex(ghRepo);
      toast.success(`Connected ${ghRepo.full_name} — indexing started`);
      setShowModal(false);
    } catch (e: any) {
      const msg = e?.response?.data?.detail || "Failed to connect repository";
      toast.error(msg);
    } finally {
      setConnecting(null);
    }
  };

  const handleDelete = async (id: string, name: string) => {
    setDeletingId(id);
    try {
      await removeRepo(id);
      toast.success(`Removed ${name}`);
    } catch {
      toast.error("Failed to delete repository");
    } finally {
      setDeletingId(null);
    }
  };

  const handleReindex = async (id: string) => {
    setReindexingId(id);
    try {
      await reindexRepo(id);
      toast.success("Re-indexing started");
    } catch {
      toast.error("Failed to start re-indexing");
    } finally {
      setReindexingId(null);
    }
  };

  // ─── Loading skeleton ────────────────────────────────────────────────────────

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <div className="h-7 w-48 animate-pulse rounded bg-muted" />
            <div className="mt-2 h-4 w-72 animate-pulse rounded bg-muted" />
          </div>
          <div className="h-9 w-44 animate-pulse rounded bg-muted" />
        </div>
        <div className="h-9 w-72 animate-pulse rounded bg-muted" />
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-16 animate-pulse rounded-xl border border-border bg-muted/30" />
          ))}
        </div>
      </div>
    );
  }

  // ─── Error state ─────────────────────────────────────────────────────────────

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center gap-4 py-20 text-center">
        <AlertCircle className="h-10 w-10 text-destructive" />
        <h2 className="text-lg font-semibold">Failed to load repositories</h2>
        <p className="max-w-md text-sm text-muted-foreground">{error}</p>
        <Button onClick={refresh} variant="outline" className="gap-2">
          <RefreshCw className="h-4 w-4" /> Retry
        </Button>
      </div>
    );
  }

  // ─── Render ──────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold">My Repositories</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Manage and index your GitHub repositories
          </p>
        </div>
        <Button className="gap-2" onClick={handleOpenModal}>
          <Github className="h-4 w-4" /> Connect Repository
        </Button>
      </div>

      {/* Search */}
      {repos.length > 0 && (
        <div className="relative max-w-sm">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search repositories..."
            className="h-9 w-full rounded-md border border-input bg-accent pl-9 pr-4 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
          />
        </div>
      )}

      {/* Empty State */}
      {repos.length === 0 && (
        <div className="flex flex-col items-center gap-4 rounded-xl border border-dashed border-border bg-card py-16 text-center">
          <FolderGit2 className="h-12 w-12 text-muted-foreground/50" />
          <h2 className="text-lg font-semibold text-card-foreground">No repositories connected</h2>
          <p className="max-w-md text-sm text-muted-foreground">
            Connect your GitHub repositories to start indexing and chatting with your code using AI.
          </p>
          <Button className="gap-2" onClick={handleOpenModal}>
            <Github className="h-4 w-4" /> Connect Your First Repository
          </Button>
        </div>
      )}

      {/* Repository Table */}
      {filtered.length > 0 && (
        <div className="overflow-hidden rounded-xl border border-border">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border bg-muted">
                <th className="px-4 py-3 text-left font-medium text-muted-foreground">Repository</th>
                <th className="px-4 py-3 text-left font-medium text-muted-foreground">Status</th>
                <th className="hidden px-4 py-3 text-left font-medium text-muted-foreground sm:table-cell">Language</th>
                <th className="hidden px-4 py-3 text-left font-medium text-muted-foreground md:table-cell">Last Indexed</th>
                <th className="px-4 py-3 text-right font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((repo) => {
                const s = repoStatus(repo);
