                            {repo.indexing_error}
                          </p>
                        )}
                      </div>
                    </td>

                    {/* Language */}
                    <td className="hidden px-4 py-3 text-muted-foreground sm:table-cell">
                      {repo.language || "—"}
                    </td>

                    {/* Last Indexed */}
                    <td className="hidden px-4 py-3 text-muted-foreground md:table-cell">
                      {timeAgo(repo.last_indexed_at)}
                    </td>

                    {/* Actions */}
                    <td className="px-4 py-3">
                      <div className="flex items-center justify-end gap-1">
                        <button
                          className="rounded p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground transition-colors disabled:opacity-40"
                          title="Re-index"
                          disabled={s === "indexing" || reindexingId === repo.id}
                          onClick={() => handleReindex(repo.id)}
                        >
                          <RefreshCw className={`h-4 w-4 ${reindexingId === repo.id ? "animate-spin" : ""}`} />
                        </button>
                        <button
                          className="rounded p-1.5 text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-colors disabled:opacity-40"
                          title="Delete"
                          disabled={deletingId === repo.id}
                          onClick={() => handleDelete(repo.id, repo.full_name)}
                        >
                          {deletingId === repo.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <Trash2 className="h-4 w-4" />
                          )}
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* No search results */}
      {repos.length > 0 && filtered.length === 0 && search && (
        <p className="py-8 text-center text-sm text-muted-foreground">
          No repositories matching "{search}"
        </p>
      )}

      {/* ─── Connect Repository Modal ────────────────────────────────────────── */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm">
          <div className="w-full max-w-lg rounded-xl border border-border bg-card p-6 shadow-lg animate-slide-up">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-card-foreground">Connect GitHub Repository</h2>
              <button
                onClick={() => setShowModal(false)}
                className="rounded p-1 text-muted-foreground hover:text-foreground transition-colors"
              >
                ✕
              </button>
            </div>
            <p className="mt-2 text-sm text-muted-foreground">
              Select a repository from your GitHub account to connect and index.
            </p>

            {/* Search GitHub repos */}
            <div className="relative mt-4">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <input
                type="text"
                value={ghSearch}
                onChange={(e) => setGhSearch(e.target.value)}
                placeholder="Filter repositories..."
                className="h-9 w-full rounded-md border border-input bg-accent pl-9 pr-4 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
              />
            </div>

            {/* GitHub repos list */}
            <div className="mt-4 max-h-80 overflow-y-auto rounded-lg border border-border">
              {githubLoading && (
                <div className="flex items-center justify-center gap-2 py-12 text-muted-foreground">
                  <Loader2 className="h-5 w-5 animate-spin" />
                  <span className="text-sm">Loading your repositories...</span>
                </div>
              )}

              {githubError && (
                <div className="flex flex-col items-center gap-2 py-12 text-center">
                  <AlertCircle className="h-6 w-6 text-destructive" />
                  <p className="text-sm text-destructive">{githubError}</p>
                  <Button variant="outline" size="sm" onClick={loadGithubRepos}>
                    Retry
                  </Button>
                </div>
              )}

              {!githubLoading && !githubError && filteredGhRepos.length === 0 && (
                <div className="py-12 text-center text-sm text-muted-foreground">
                  {githubRepos.length > 0
                    ? "All matching repositories are already connected."
                    : "No repositories found on your GitHub account."}
                </div>
              )}

              {!githubLoading &&
                !githubError &&
                filteredGhRepos.map((ghRepo) => (
                  <div
                    key={ghRepo.full_name}
                    className="flex items-center justify-between border-b border-border px-4 py-3 last:border-0 hover:bg-accent/50 transition-colors"
                  >
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        <p className="truncate font-medium text-sm text-foreground">{ghRepo.full_name}</p>
                        {ghRepo.private && <Lock className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />}
                      </div>
                      <div className="mt-0.5 flex items-center gap-3 text-xs text-muted-foreground">
                        {ghRepo.language && <span>{ghRepo.language}</span>}
                        {ghRepo.stars > 0 && (
                          <span className="flex items-center gap-0.5">
                            <Star className="h-3 w-3" /> {ghRepo.stars}
                          </span>
                        )}
                      </div>
                    </div>
                    <Button
                      size="sm"
                      variant="outline"
                      disabled={connecting === ghRepo.full_name}
                      onClick={() => handleConnect(ghRepo)}
                      className="ml-3 shrink-0"
                    >
                      {connecting === ghRepo.full_name ? (
                        <Loader2 className="mr-1 h-3.5 w-3.5 animate-spin" />
                      ) : null}
                      {connecting === ghRepo.full_name ? "Connecting…" : "Connect & Index"}
                    </Button>
                  </div>
                ))}
            </div>

            {/* Footer */}
            <div className="mt-4 flex justify-end">
              <Button variant="outline" onClick={() => setShowModal(false)}>
                Close
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useOrganization } from "@/contexts/OrganizationContext";
import { organizationsApi, OrganizationCreate, OrganizationWithRole } from "@/lib/api/organizations";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { Building2, Plus, Users, Settings as SettingsIcon, LogOut } from "lucide-react";
import { OrganizationMembers } from "@/components/organizations/OrganizationMembers";

export default function OrganizationsSettings() {
    const userStr = localStorage.getItem('user');
    const user = userStr ? JSON.parse(userStr) : null;
    const {
        organizations,
        currentOrganization,
        setCurrentOrganizationId,
        refreshOrganizations,
        isLoading
    } = useOrganization();

    const [isCreating, setIsCreating] = useState(false);
    const [newOrgName, setNewOrgName] = useState("");
    const [managingOrgId, setManagingOrgId] = useState<string | null>(null);

    const handleCreateOrganization = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newOrgName.trim()) return;

        try {
            setIsCreating(true);
            const newOrg = await organizationsApi.create({ name: newOrgName });
            toast.success(`Organization "${newOrg.name}" created successfully`);
            setNewOrgName("");
            await refreshOrganizations();
            // Auto-switch to the new org
            setCurrentOrganizationId(newOrg.id);
        } catch (error: any) {
            toast.error(error.response?.data?.detail || "Failed to create organization");
        } finally {
            setIsCreating(false);
        }
    };

    const handleLeaveOrganization = async (orgId: string, orgName: string) => {
        if (!confirm(`Are you sure you want to leave ${orgName}?`)) return;

        try {
            if (!user) return;
            await organizationsApi.removeMember(orgId, user.id);
            toast.success(`Successfully left ${orgName}`);

            if (currentOrganization?.id === orgId) {
                setCurrentOrganizationId(null);
            }

            refreshOrganizations();
        } catch (error: any) {
            toast.error(error.response?.data?.detail || "Failed to leave organization");
        }
    };

    return (
        <div className="space-y-6">
            <div>
                <h2 className="text-2xl font-semibold tracking-tight">Organizations</h2>
                <p className="text-sm text-muted-foreground mt-1">
                    Create and manage organizations to collaborate on repositories with your team.
                </p>
            </div>

            <div className="grid gap-6 md:grid-cols-2">
                {/* Create Organization Card */}
                <Card>
                    <CardHeader>
                        <CardTitle className="flex items-center gap-2 text-lg">
                            <Plus className="h-5 w-5" />
                            New Organization
                        </CardTitle>
                        <CardDescription>
                            Create a new shared workspace for your team.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <form onSubmit={handleCreateOrganization} className="space-y-4">
                            <div className="space-y-2">
                                <Label htmlFor="orgName">Organization Name</Label>
                                <Input
                                    id="orgName"
                                    placeholder="e.g. Acme Corp"
                                    value={newOrgName}
                                    onChange={(e) => setNewOrgName(e.target.value)}
                                    disabled={isCreating}
                                    required
                                />
                            </div>
                            <Button type="submit" disabled={isCreating || !newOrgName.trim()}>
                                {isCreating ? "Creating..." : "Create Organization"}
                            </Button>
                        </form>
                    </CardContent>
                </Card>

                {/* List of Organizations */}
                <div className="space-y-4">
                    <h3 className="text-sm font-medium text-muted-foreground flex items-center gap-2">
                        <Building2 className="h-4 w-4" />
                        Your Organizations
                    </h3>

                    {isLoading ? (
                        <div className="flex justify-center p-8">
                            <div className="animate-spin h-6 w-6 border-2 border-primary border-t-transparent rounded-full" />
                        </div>
                    ) : organizations.length === 0 ? (
                        <Card className="border-dashed bg-transparent">
                            <CardContent className="flex flex-col items-center justify-center p-6 text-center text-muted-foreground h-40">
                                <Building2 className="h-8 w-8 mb-2 opacity-50" />
                                <p>You don't belong to any organizations yet.</p>
                            </CardContent>
                        </Card>
                    ) : (
                        <div className="space-y-3">
                            {organizations.map((org) => (
                                <Card key={org.id} className={currentOrganization?.id === org.id ? 'border-primary shadow-sm' : ''}>
                                    <CardHeader className="p-4 pb-2">
                                        <div className="flex items-center justify-between">
                                            <CardTitle className="text-base flex items-center gap-2">
                                                {org.name}
                                                {org.role === 'owner' && (
                                                    <span className="text-[10px] uppercase font-bold tracking-wider bg-primary/10 text-primary px-2 py-0.5 rounded-full">Owner</span>
                                                )}
                                                {org.role === 'admin' && (
                                                    <span className="text-[10px] uppercase font-bold tracking-wider bg-blue-500/10 text-blue-500 px-2 py-0.5 rounded-full">Admin</span>
                                                )}
                                                {currentOrganization?.id === org.id && (
                                                    <span className="text-[10px] uppercase font-bold tracking-wider bg-green-500/10 text-green-500 px-2 py-0.5 rounded-full flex items-center gap-1">
                                                        <span className="h-1.5 w-1.5 rounded-full bg-green-500"></span> Active
                                                    </span>
                                                )}
                                            </CardTitle>
                                        </div>
                                    </CardHeader>
                                    <CardContent className="p-4 pt-0">
                                        <div className="flex items-center justify-between mt-4">
                                            <Button
                                                variant={currentOrganization?.id === org.id ? "secondary" : "outline"}
                                                size="sm"
                                                onClick={() => setCurrentOrganizationId(org.id)}
                                                disabled={currentOrganization?.id === org.id}
                                            >
                                                {currentOrganization?.id === org.id ? "Currently Active" : "Switch To"}
                                            </Button>

                                            <div className="flex gap-2">
                                                <Button variant="ghost" size="icon" title="Organization Settings" disabled={org.role === 'member'}>
                                                    <SettingsIcon className="h-4 w-4 text-muted-foreground" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    title="Manage Members"
                                                    disabled={org.role === 'member'}
                                                    onClick={() => setManagingOrgId(org.id)}
                                                >
                                                    <Users className="h-4 w-4 text-muted-foreground" />
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="icon"
                                                    className="text-destructive hover:text-destructive hover:bg-destructive/10"
                                                    title="Leave Organization"
                                                    onClick={() => handleLeaveOrganization(org.id, org.name)}
                                                    disabled={org.role === 'owner'} // Owners should delete or transfer, not just leave usually, handle better later
                                                >
                                                    <LogOut className="h-4 w-4" />
                                                </Button>
                                            </div>
                                        </div>
                                    </CardContent>
                                </Card>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {managingOrgId && (
                <OrganizationMembers
                    organizationId={managingOrgId}
                    organizationName={organizations.find(o => o.id === managingOrgId)?.name || ""}
                    currentUserRole={organizations.find(o => o.id === managingOrgId)?.role || "member"}
                    open={!!managingOrgId}
                    onOpenChange={(open) => !open && setManagingOrgId(null)}
                />
            )}
        </div>
    );
}

/**
 * DevIntelSidebarProvider — VS Code Webview sidebar that renders an
 * AI chat UI calling the DevIntel backend with SSE streaming.
 *
 * Supports:
 *  - Repository selection + streaming RAG chat
 *  - "Review File" trigger from the editor command
 *  - Auth state change notifications
 */

import * as vscode from "vscode";
import { DevIntelAuth } from "./auth";

export class DevIntelSidebarProvider implements vscode.WebviewViewProvider {
    private _view?: vscode.WebviewView;

    constructor(
        private readonly _extensionUri: vscode.Uri,
        private readonly _auth: DevIntelAuth
    ) { }

    resolveWebviewView(
        webviewView: vscode.WebviewView,
        _context: vscode.WebviewViewResolveContext,
        _token: vscode.CancellationToken
    ): void {
        this._view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,
            localResourceRoots: [this._extensionUri],
        };

        webviewView.webview.html = this._getHtml();

        // Handle messages from the webview
        webviewView.webview.onDidReceiveMessage(async (msg) => {
            switch (msg.type) {
                case "ready":
                    await this._sendConfig();
                    break;

                case "chat": {
                    const { repoId, question, history } = msg;
                    await this._streamChat(webviewView.webview, repoId, question, history);
                    break;
                }

                case "getRepos": {
                    await this._sendRepos(webviewView.webview);
                    break;
                }

                case "setToken": {
                    const token = await vscode.window.showInputBox({
                        prompt: "Paste your DevIntel API token (JWT from app settings)",
                        password: true,
                        placeHolder: "eyJ...",
                    });
                    if (token) {
                        await this._auth.setToken(token);
                        await this._sendConfig();
                        webviewView.webview.postMessage({ type: "authUpdated" });
                    }
                    break;
                }
            }
        });
    }

    /** Called by extension.ts when auth changes externally */
    notifyAuthChanged(): void {
        if (this._view) {
            this._sendConfig();
        }
    }

    /** Called when user runs "DevIntel: Review Current File" command */
    async triggerFileReview(filePath: string, content: string, language: string): Promise<void> {
        if (!this._view) return;
        this._view.webview.postMessage({
            type: "reviewFile",
            filePath,
            content: content.slice(0, 8000), // limit context
            language,
        });
    }

    // ─── Private helpers ─────────────────────────────────────────────────────

    private async _sendConfig(): Promise<void> {
        if (!this._view) return;
        const token = await this._auth.getToken();
        const apiBaseUrl = this._auth.getApiBaseUrl();
        this._view.webview.postMessage({
            type: "config",
            apiBaseUrl,
            hasToken: !!token,
        });
    }

    private async _sendRepos(webview: vscode.Webview): Promise<void> {
        const token = await this._auth.getToken();
        const headers = await this._auth.buildHeaders();
        const apiBaseUrl = this._auth.getApiBaseUrl();

        try {
            const resp = await fetch(`${apiBaseUrl}/api/v1/repos`, { headers });
            if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
            const data = (await resp.json()) as { repositories: { id: string; full_name: string; indexed_status: boolean }[] };
            webview.postMessage({ type: "repos", repositories: data.repositories || [] });
        } catch (e: any) {
            webview.postMessage({ type: "repos", repositories: [], error: e.message });
        }
    }

    private async _streamChat(
        webview: vscode.Webview,
        repoId: string,
        question: string,
        history: { role: string; content: string }[]
    ): Promise<void> {
        const headers = await this._auth.buildHeaders();
        const apiBaseUrl = this._auth.getApiBaseUrl();

        try {
            const resp = await fetch(`${apiBaseUrl}/api/v1/chat`, {
                method: "POST",
                headers,
                body: JSON.stringify({ repository_id: repoId, question, chat_history: history }),
            });

            if (!resp.ok || !resp.body) {
                webview.postMessage({ type: "chatError", message: `HTTP ${resp.status}` });
                return;
            }

            const reader = resp.body.getReader();
            const decoder = new TextDecoder();
            let buffer = "";

            while (true) {
                const { done, value } = await reader.read();
                if (done) break;

                buffer += decoder.decode(value, { stream: true });
                const lines = buffer.split("\n");
                buffer = lines.pop() ?? "";

                for (const line of lines) {
                    if (!line.startsWith("data: ")) continue;
                    try {
                        const data = JSON.parse(line.slice(6));
                        if (data.error) {
                            webview.postMessage({ type: "chatError", message: data.error });
                            return;
                        }
                        if (data.content) {
                            webview.postMessage({ type: "chatChunk", content: data.content });
                        }
                        if (data.done) {
                            webview.postMessage({
                                type: "chatDone",
                                costUsd: data.cost_usd,
                                tokenUsage: data.token_usage,
                            });
                        }
                    } catch {
                        // skip malformed SSE frames
                    }
                }
            }
        } catch (e: any) {
            webview.postMessage({ type: "chatError", message: e.message });
        }
    }

    private _getHtml(): string {
        return /* html */ `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DevIntel AI Chat</title>
  <style>
    :root {
      --radius: 6px;
