const axisTickStyle = { fill: "hsl(220, 10%, 55%)", fontSize: 11 };
const tooltipStyle = {
  backgroundColor: "hsl(222, 16%, 9%)",
  border: "1px solid hsl(222, 16%, 16%)",
  borderRadius: "8px",
  color: "hsl(210, 20%, 95%)",
  fontSize: 12,
};

export default function AnalyticsPage() {
  const [repos, setRepos] = useState<Repository[]>([]);
  const [analytics, setAnalytics] = useState<AnalyticsDashboard | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchData() {
      try {
        const [repoResult, analyticsResult] = await Promise.allSettled([
          apiClient.get<{ repositories: Repository[]; total: number }>('/api/v1/repos'),
          apiClient.get<AnalyticsDashboard>('/api/v1/analytics/dashboard'),
        ]);

        if (repoResult.status === 'fulfilled') {
          setRepos(repoResult.value.repositories || []);
        }
        if (analyticsResult.status === 'fulfilled') {
          setAnalytics(analyticsResult.value);
        }
      } catch (err) {
        console.error('Failed to fetch analytics data:', err);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  // Build language distribution chart from repo data
  const languageStats = repos.reduce((acc, repo) => {
    const lang = repo.language || 'Unknown';
    acc[lang] = (acc[lang] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const languageChartData = Object.entries(languageStats)
    .map(([language, count]) => ({ language, count }))
    .sort((a, b) => b.count - a.count);

  const indexedCount = repos.filter(r => r.indexed_status === true).length;
  const pendingCount = repos.filter(r => !r.indexed_status && r.indexing_progress > 0).length;
  const notIndexedCount = repos.length - indexedCount - pendingCount;

  const statusData = [
    { status: 'Indexed', count: indexedCount },
    { status: 'In Progress', count: pendingCount },
    { status: 'Not Indexed', count: notIndexedCount },
  ].filter(d => d.count > 0);

  // Format usage trend dates for display
  const usageTrendData = (analytics?.usage_trend || []).map(d => ({
    ...d,
    date: new Date(d.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
  }));

  const monthlyCostData = ((analytics as any)?.monthly_cost || []).map(
    (d: { date: string; cost_usd: number }) => ({
      date: new Date(d.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      cost: d.cost_usd,
    })
  );

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-semibold">Analytics</h1>
        <p className="mt-1 text-sm text-muted-foreground">Usage insights and code intelligence trends</p>
      </div>

      {repos.length === 0 && !analytics ? (
        <div className="flex flex-col items-center justify-center py-16 rounded-xl border border-dashed border-border">
          <BarChart3 className="h-10 w-10 text-muted-foreground" />
          <p className="mt-3 text-sm font-medium text-foreground">No data yet</p>
          <p className="mt-1 text-xs text-muted-foreground">Connect and index repositories to see analytics</p>
        </div>
      ) : (
        <>
          {/* Top stat cards */}
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <div className="rounded-xl border border-border bg-card p-5">
              <div className="flex items-center gap-2 mb-2">
                <MessageSquare className="h-4 w-4 text-primary" />
                <p className="text-sm text-muted-foreground">Total Queries</p>
              </div>
              <p className="text-3xl font-bold text-foreground">
                {analytics ? analytics.total_queries.toLocaleString() : repos.length}
              </p>
            </div>
            <div className="rounded-xl border border-border bg-card p-5">
              <div className="flex items-center gap-2 mb-2">
                <Coins className="h-4 w-4 text-amber-500" />
                <p className="text-sm text-muted-foreground">Tokens Used</p>
              </div>
              <p className="text-3xl font-bold text-foreground">
                {analytics ? `${(analytics.total_tokens / 1000).toFixed(1)}k` : '—'}
              </p>
            </div>
            <div className="rounded-xl border border-border bg-card p-5">
              <div className="flex items-center gap-2 mb-2">
                <TrendingUp className="h-4 w-4 text-green-500" />
                <p className="text-sm text-muted-foreground">Indexed Repos</p>
              </div>
              <p className="text-3xl font-bold text-green-500">{indexedCount}</p>
            </div>
            <div className="rounded-xl border border-border bg-card p-5">
              <div className="flex items-center gap-2 mb-2">
                <DollarSign className="h-4 w-4 text-emerald-400" />
                <p className="text-sm text-muted-foreground">Total Spend</p>
              </div>
              <p className="text-3xl font-bold text-emerald-400">
                {analytics?.total_cost_usd != null
                  ? `$${analytics.total_cost_usd.toFixed(4)}`
                  : '—'}
              </p>
            </div>
          </div>

          {/* Charts row */}
          <div className="grid gap-6 lg:grid-cols-2">
            {/* Queries Over Time */}
            {usageTrendData.length > 0 ? (
              <div className="rounded-xl border border-border bg-card p-5">
                <h2 className="font-semibold text-card-foreground">Queries Over Time</h2>
                <p className="mt-1 text-xs text-muted-foreground">Daily AI query activity (last 30 days)</p>
                <div className="mt-4 h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={usageTrendData}>
                      <defs>
                        <linearGradient id="queryGradient" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="hsl(217, 91%, 60%)" stopOpacity={0.3} />
                          <stop offset="95%" stopColor="hsl(217, 91%, 60%)" stopOpacity={0} />
                        </linearGradient>
                      </defs>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                      <XAxis dataKey="date" tick={axisTickStyle} />
                      <YAxis tick={axisTickStyle} />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Area
                        type="monotone"
                        dataKey="queries"
                        stroke="hsl(217, 91%, 60%)"
                        strokeWidth={2}
                        fill="url(#queryGradient)"
                      />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </div>
            ) : (
              <div className="rounded-xl border border-border bg-card p-5">
                <h2 className="font-semibold text-card-foreground">Queries Over Time</h2>
                <p className="mt-1 text-xs text-muted-foreground">Daily AI query activity</p>
                <div className="flex items-center justify-center h-64 text-muted-foreground text-sm">
                  No query data yet — start chatting with your repos!
                </div>
              </div>
            )}

            {/* Top Repositories by Usage */}
            {analytics && analytics.top_repositories.length > 0 ? (
              <div className="rounded-xl border border-border bg-card p-5">
                <h2 className="font-semibold text-card-foreground">Top Repositories</h2>
                <p className="mt-1 text-xs text-muted-foreground">Most queried repositories</p>
                <div className="mt-4 h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={analytics.top_repositories} layout="vertical">
                      <CartesianGrid strokeDasharray="3 3" stroke={gridColor} horizontal={false} />
                      <XAxis type="number" tick={axisTickStyle} />
                      <YAxis
                        type="category"
                        dataKey="repo_name"
                        tick={axisTickStyle}
                        width={90}
                        tickFormatter={(v: string) => v.split('/').pop() || v}
                      />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Bar dataKey="queries" fill="hsl(217, 91%, 60%)" radius={[0, 4, 4, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            ) : languageChartData.length > 0 ? (
              <div className="rounded-xl border border-border bg-card p-5">
                <h2 className="font-semibold text-card-foreground">Language Distribution</h2>
                <p className="mt-1 text-xs text-muted-foreground">Languages across your repositories</p>
                <div className="mt-4 h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={languageChartData}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                      <XAxis dataKey="language" tick={axisTickStyle} />
                      <YAxis tick={axisTickStyle} />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Bar dataKey="count" fill="hsl(142, 71%, 45%)" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            ) : null}
          </div>

          {/* Cost Over Time chart */}
          {monthlyCostData.length > 0 && (
            <div className="rounded-xl border border-border bg-card p-5">
              <h2 className="font-semibold text-card-foreground">Cost Over Time</h2>
              <p className="mt-1 text-xs text-muted-foreground">Daily AI spend — last 30 days (USD)</p>
              <div className="mt-4 h-56">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={monthlyCostData}>
                    <defs>
                      <linearGradient id="costGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="hsl(142, 71%, 45%)" stopOpacity={0.3} />
                        <stop offset="95%" stopColor="hsl(142, 71%, 45%)" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                    <XAxis dataKey="date" tick={axisTickStyle} />
                    <YAxis tick={axisTickStyle} tickFormatter={(v: number) => `$${v.toFixed(4)}`} />
                    <Tooltip
                      contentStyle={tooltipStyle}
                      formatter={(v: number) => [`$${v.toFixed(5)}`, "Cost (USD)"]}
                    />
                    <Area
                      type="monotone"
                      dataKey="cost"
                      stroke="hsl(142, 71%, 45%)"
                      strokeWidth={2}
                      fill="url(#costGradient)"
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </div>
          )}

          {/* Second charts row */}
          <div className="grid gap-6 lg:grid-cols-2">
            {/* Language Distribution */}
            {languageChartData.length > 0 && analytics?.top_repositories.length > 0 && (
              <div className="rounded-xl border border-border bg-card p-5">
                <h2 className="font-semibold text-card-foreground">Language Distribution</h2>
                <p className="mt-1 text-xs text-muted-foreground">Languages across your repositories</p>
                <div className="mt-4 h-56">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={languageChartData}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                      <XAxis dataKey="language" tick={axisTickStyle} />
                      <YAxis tick={axisTickStyle} />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Bar dataKey="count" fill="hsl(142, 71%, 45%)" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}

            {/* Indexing Status */}
            {statusData.length > 0 && (
              <div className="rounded-xl border border-border bg-card p-5">
                <h2 className="font-semibold text-card-foreground">Indexing Status</h2>
                <p className="mt-1 text-xs text-muted-foreground">Repository indexing progress</p>
                <div className="mt-4 h-56">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={statusData}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridColor} />
                      <XAxis dataKey="status" tick={axisTickStyle} />
                      <YAxis tick={axisTickStyle} />
                      <Tooltip contentStyle={tooltipStyle} />
                      <Bar dataKey="count" fill="hsl(142, 71%, 45%)" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}
          </div>

          {/* Repository List */}
          <div className="rounded-xl border border-border bg-card p-5">
            <h2 className="font-semibold text-card-foreground">All Repositories</h2>
            <p className="mt-1 text-xs text-muted-foreground">Complete overview of your connected repos</p>
            <div className="mt-4 space-y-3">
              {repos.map((repo, i) => (
                <div key={repo.id} className="flex items-center gap-4">
                  <span className="w-4 text-xs text-muted-foreground">{i + 1}</span>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between">
                      <p className="truncate text-sm font-mono text-card-foreground">{repo.full_name}</p>
                      <span className="shrink-0 text-xs text-muted-foreground">
                        {repo.indexed_status ? '✅ Indexed' : (repo.indexing_progress > 0 ? '⏳ Indexing' : '⬜ Not indexed')}
                      </span>
                    </div>
                    <div className="mt-1.5 h-1.5 w-full rounded-full bg-muted">
                      <div
                        className={`h-1.5 rounded-full transition-all ${repo.indexed_status ? 'bg-green-500' : (repo.indexing_progress > 0 ? 'bg-amber-500' : 'bg-muted-foreground/30')}`}
                        style={{ width: repo.indexed_status ? '100%' : (repo.indexing_progress > 0 ? `${repo.indexing_progress}%` : '0%') }}
                      />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import {
    Shield,
    FileText,
    Wrench,
    TestTube,
    Lock,
    GitBranch,
    Loader2,
    RefreshCw,
    AlertTriangle,
    Lightbulb,
    ChevronDown,
    Check,
    Wand2,
    CheckCircle2,
    XCircle
} from "lucide-react";
import { apiClient } from "@/lib/api-client";
import type { CodeHealthReport, Repository, AutoFixResponse } from "@/lib/types";

/** Colour coding for scores */
function scoreColor(score: number) {
    if (score >= 75) return "text-green-400";
    if (score >= 50) return "text-amber-400";
    return "text-red-400";
}

function scoreRingColor(score: number) {
    if (score >= 75) return "#22c55e";
    if (score >= 50) return "#f59e0b";
    return "#ef4444";
}

function scoreLabel(score: number) {
    if (score >= 80) return "Excellent";
    if (score >= 65) return "Good";
    if (score >= 50) return "Fair";
    if (score >= 35) return "Poor";
    return "Critical";
}

/** Radial gauge SVG — single-ring progress arc */
function ScoreGauge({ score }: { score: number }) {
    const radius = 72;
    const circ = 2 * Math.PI * radius;
    const offset = circ - (score / 100) * circ;
    const color = scoreRingColor(score);

    return (
        <div className="relative flex items-center justify-center">
            <svg width="180" height="180" viewBox="0 0 180 180" className="-rotate-90">
                <circle cx="90" cy="90" r={radius} fill="none" stroke="hsl(222,16%,16%)" strokeWidth="14" />
                <circle
                    cx="90"
                    cy="90"
                    r={radius}
                    fill="none"
                    stroke={color}
                    strokeWidth="14"
                    strokeDasharray={circ}
                    strokeDashoffset={offset}
                    strokeLinecap="round"
                    style={{ transition: "stroke-dashoffset 1s ease" }}
                />
            </svg>
            <div className="absolute flex flex-col items-center">
                <span className={`text-4xl font-bold ${scoreColor(score)}`}>{Math.round(score)}</span>
                <span className="text-xs text-muted-foreground mt-1">{scoreLabel(score)}</span>
            </div>
        </div>
    );
}

/** Generic dimension bar */
function DimensionBar({
    icon: Icon,
    label,
    score,
}: {
    icon: React.ElementType;
    label: string;
    score: number;
}) {
    const color = scoreRingColor(score);
    return (
        <div className="space-y-1.5">
            <div className="flex items-center justify-between text-sm">
                <span className="flex items-center gap-1.5 text-muted-foreground">
                    <Icon className="h-3.5 w-3.5" />
                    {label}
                </span>
                <span className={`font-semibold ${scoreColor(score)}`}>{Math.round(score)}</span>
            </div>
            <div className="h-2 w-full rounded-full bg-muted overflow-hidden">
                <div
                    className="h-2 rounded-full transition-all duration-700"
                    style={{ width: `${score}%`, backgroundColor: color }}
                />
            </div>
        </div>
    );
}

export default function CodeHealthPage() {
    const [repos, setRepos] = useState<Repository[]>([]);
    const [selectedRepo, setSelectedRepo] = useState<Repository | null>(null);
    const [health, setHealth] = useState<CodeHealthReport | null>(null);
    const [loadingRepos, setLoadingRepos] = useState(true);
    const [loadingHealth, setLoadingHealth] = useState(false);
    const [refreshing, setRefreshing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [dropdownOpen, setDropdownOpen] = useState(false);
    
    // Auto-Fix states
    const [fixingIssueIndex, setFixingIssueIndex] = useState<number | null>(null);
    const [fixedIssues, setFixedIssues] = useState<Record<number, { success: boolean, url?: string, message?: string }>>({});

    // Load repos
    useEffect(() => {
        apiClient
            .get<{ repositories: Repository[] }>("/api/v1/repos")
            .then((d) => {
                const list = d.repositories || [];
                setRepos(list);
                const indexed = list.find((r) => r.indexed_status);
                if (indexed) setSelectedRepo(indexed);
            })
            .finally(() => setLoadingRepos(false));
    }, []);

    // Load health when repo changes
    useEffect(() => {
        if (!selectedRepo) return;
        setHealth(null);
        setError(null);
        setLoadingHealth(true);
        apiClient
            .get<CodeHealthReport>(`/api/v1/repos/${selectedRepo.id}/health`)
            .then(setHealth)
            .catch((e) => {
                const msg = e?.response?.data?.detail || e?.message || "Failed to load health report";
                setError(msg);
            })
            .finally(() => setLoadingHealth(false));
    }, [selectedRepo]);

    async function handleRefresh() {
        if (!selectedRepo) return;
        setRefreshing(true);
        setError(null);
        try {
            await apiClient.post(`/api/v1/repos/${selectedRepo.id}/health/refresh`);
            // Poll for result
            let attempts = 0;
            const poll = setInterval(async () => {
                attempts++;
                try {
                    const result = await apiClient.get<CodeHealthReport>(
                        `/api/v1/repos/${selectedRepo.id}/health`
                    );
                    const prev = health?.computed_at;
                    if (!prev || result.computed_at !== prev) {
                        setHealth(result);
                        setRefreshing(false);
                        clearInterval(poll);
                    }
                } catch {
                    // Still computing
                }
                if (attempts > 30) {
                    clearInterval(poll);
                    setRefreshing(false);
                }
            }, 3000);
        } catch (e: any) {
            setError(e?.response?.data?.detail || "Failed to trigger refresh");
            setRefreshing(false);
        }
    }

    const indexedRepos = repos.filter((r) => r.indexed_status);

    async function handleAutoFix(issueIndex: number, issueDescription: string) {
        if (!selectedRepo) return;
        setFixingIssueIndex(issueIndex);
        try {
            const res = await apiClient.post<AutoFixResponse>(
                `/api/v1/repos/${selectedRepo.id}/auto-fix`,
                { issue_description: issueDescription }
            );
            
            setFixedIssues(prev => ({
                ...prev,
                [issueIndex]: {
                    success: res.status === 'success',
                    url: res.pr_url,
                    message: res.message
                }
            }));
            
        } catch (e: any) {
            setFixedIssues(prev => ({
                ...prev,
                [issueIndex]: {
                    success: false,
                    message: e?.response?.data?.detail || e?.message || "Failed to generate fix"
                }
            }));
        } finally {
            setFixingIssueIndex(null);
        }
    }

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-semibold">Code Health</h1>
                    <p className="mt-1 text-sm text-muted-foreground">
                        AI-powered quality analysis of your indexed repository
                    </p>
                </div>

                <div className="flex items-center gap-2">
                    {/* Repo selector */}
                    <div className="relative">
                        <button
                            onClick={() => setDropdownOpen((v) => !v)}
                            className="flex items-center gap-2 h-9 rounded-lg border border-input bg-card px-3 text-sm text-foreground hover:border-primary transition-colors"
                        >
                            <GitBranch className="h-3.5 w-3.5 text-muted-foreground" />
                            <span className="max-w-[180px] truncate">
                                {selectedRepo ? selectedRepo.full_name : "Select repository"}
                            </span>
                            <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform ${dropdownOpen ? "rotate-180" : ""}`} />
                        </button>
                        {dropdownOpen && (
                            <div className="absolute right-0 top-full mt-1 z-50 w-64 rounded-lg border border-border bg-card shadow-lg overflow-hidden">
                                {indexedRepos.length === 0 ? (
                                    <p className="px-3 py-2.5 text-sm text-muted-foreground">No indexed repositories</p>
                                ) : (
                                    indexedRepos.map((r) => (
                                        <button
                                            key={r.id}
                                            onClick={() => { setSelectedRepo(r); setDropdownOpen(false); }}
                                            className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-accent transition-colors"
                                        >
                                            <span className="flex-1 truncate">{r.full_name}</span>
                                            {selectedRepo?.id === r.id && <Check className="h-3.5 w-3.5 text-primary" />}
                                        </button>
                                    ))
                                )}
                            </div>
                        )}
                    </div>

                    {/* Refresh */}
                    {selectedRepo && (
                        <button
                            onClick={handleRefresh}
                            disabled={refreshing || loadingHealth}
                            className="flex items-center gap-1.5 h-9 rounded-lg border border-input bg-card px-3 text-sm text-muted-foreground hover:text-foreground hover:border-primary transition-colors disabled:opacity-50"
                        >
                            <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? "animate-spin" : ""}`} />
                            {refreshing ? "Analyzing…" : "Refresh"}
                        </button>
                    )}
                </div>
            </div>

            {/* Loading */}
            {(loadingHealth || loadingRepos) && (
                <div className="flex items-center justify-center py-20">
                    <Loader2 className="h-7 w-7 animate-spin text-muted-foreground" />
                </div>
            )}

            {/* Error */}
            {!loadingHealth && error && (
                <div className="flex items-start gap-3 rounded-xl border border-amber-500/30 bg-amber-500/5 p-4">
                    <AlertTriangle className="h-5 w-5 text-amber-400 shrink-0 mt-0.5" />
                    <div>
                        <p className="text-sm font-medium text-amber-400">Health report unavailable</p>
                        <p className="mt-1 text-xs text-muted-foreground">{error}</p>
                        {refreshing === false && selectedRepo && (
                            <button
                                onClick={handleRefresh}
                                className="mt-2 text-xs text-primary hover:underline"
                            >
                                Trigger analysis →
                            </button>
                        )}
                    </div>
                </div>
            )}

            {/* No repo selected */}
            {!loadingRepos && !selectedRepo && !error && (
                <div className="flex flex-col items-center justify-center py-20 rounded-xl border border-dashed border-border">
                    <Shield className="h-10 w-10 text-muted-foreground" />
                    <p className="mt-3 text-sm font-medium">Select an indexed repository</p>
                    <p className="mt-1 text-xs text-muted-foreground">
                        Health reports are generated automatically after indexing
                    </p>
                </div>
            )}

            {/* Health Report */}
            {!loadingHealth && health && (
                <>
                    {/* Top row: gauge + dimensions */}
                    <div className="grid gap-6 lg:grid-cols-3">
                        {/* Overall Score */}
                        <div className="rounded-xl border border-border bg-card p-6 flex flex-col items-center gap-4">
                            <h2 className="font-semibold text-card-foreground self-start">Overall Score</h2>
                            <ScoreGauge score={health.overall_score} />
                            <div className="w-full text-center space-y-1">
                                <p className="text-xs text-muted-foreground">{health.language_detected || "Unknown"} repository</p>
                                <p className="text-xs text-muted-foreground">{health.files_analyzed} file chunks analyzed</p>
                                {health.computed_at && (
                                    <p className="text-xs text-muted-foreground">
                                        Computed {new Date(health.computed_at).toLocaleString()}
                                    </p>
                                )}
                            </div>
                        </div>

                        {/* Dimension Breakdown */}
                        <div className="lg:col-span-2 rounded-xl border border-border bg-card p-6 space-y-5">
                            <h2 className="font-semibold text-card-foreground">Dimension Breakdown</h2>
                            <DimensionBar icon={Wrench} label="Complexity" score={health.dimensions.complexity} />
                            <DimensionBar icon={FileText} label="Documentation" score={health.dimensions.documentation} />
                            <DimensionBar icon={Shield} label="Maintainability" score={health.dimensions.maintainability} />
                            <DimensionBar icon={TestTube} label="Test Coverage" score={health.dimensions.test_coverage} />
                            <DimensionBar icon={Lock} label="Security" score={health.dimensions.security} />
                        </div>
                    </div>

                    {/* Summary */}
                    <div className="rounded-xl border border-border bg-card p-5">
                        <h2 className="font-semibold text-card-foreground mb-3">Executive Summary</h2>
                        <p className="text-sm text-muted-foreground leading-relaxed">{health.summary}</p>
                    </div>

                    {/* Issues + Recommendations */}
                    <div className="grid gap-6 lg:grid-cols-2">
                        {health.top_issues.length > 0 && (
                            <div className="rounded-xl border border-border bg-card p-5">
                                <h2 className="font-semibold text-card-foreground mb-3 flex items-center gap-2">
                                    <AlertTriangle className="h-4 w-4 text-amber-400" />
                                    Top Issues
                                </h2>
                                <ul className="space-y-3">
                                    {health.top_issues.map((issue, i) => {
                                        const isFixing = fixingIssueIndex === i;
                                        const fixState = fixedIssues[i];
                                        
                                        return (
                                            <li key={i} className="flex flex-col gap-2 p-3 rounded-lg border border-border bg-muted/30 transition-colors hover:bg-muted/50">
                                                <div className="flex items-start gap-2 text-sm text-muted-foreground">
                                                    <span className="mt-1.5 h-1.5 w-1.5 rounded-full bg-amber-400 shrink-0" />
                                                    <span className="flex-1">{issue}</span>
                                                    
                                                    {!fixState?.success && (
                                                        <button 
                                                            onClick={() => handleAutoFix(i, issue)}
                                                            disabled={isFixing}
                                                            className="flex items-center gap-1.5 shrink-0 ml-4 px-2.5 py-1 text-xs font-medium rounded-md border border-primary/30 text-primary bg-primary/10 hover:bg-primary/20 transition-colors disabled:opacity-50"
                                                        >
                                                            {isFixing ? (
                                                                <Loader2 className="h-3 w-3 animate-spin"/>
                                                            ) : (
                                                                <Wand2 className="h-3 w-3"/>
                                                            )}
                                                            {isFixing ? "Fixing..." : "Auto-Fix"}
                                                        </button>
                                                    )}
                                                </div>
                                                
                                                {fixState && (
                                                    <div className={`flex items-start gap-2 mt-1 text-xs rounded-md px-2 py-1.5 ${fixState.success ? 'bg-green-500/10 text-green-500 w-fit' : 'bg-red-500/10 text-red-500'}`}>
                                                        {fixState.success ? (
                                                            <>
                                                                <CheckCircle2 className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                                                                <span>Fix generated! <a href={fixState.url!} target="_blank" rel="noreferrer" className="underline hover:text-green-400 font-medium">View PR #{fixState.url!.split('/').pop()}</a></span>
                                                            </>
                                                        ) : (
                                                            <>
                                                                <XCircle className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                                                                <span>{fixState.message || "Failed to generate fix"}</span>
                                                            </>
                                                        )}
                                                    </div>
                                                )}
                                            </li>
                                        );
                                    })}
                                </ul>
                            </div>
                        )}

                        {health.recommendations.length > 0 && (
                            <div className="rounded-xl border border-border bg-card p-5">
                                <h2 className="font-semibold text-card-foreground mb-3 flex items-center gap-2">
                                    <Lightbulb className="h-4 w-4 text-primary" />
                                    Recommendations
                                </h2>
                                <ul className="space-y-2">
                                    {health.recommendations.map((rec, i) => (
                                        <li key={i} className="flex items-start gap-2 text-sm text-muted-foreground">
                                            <span className="mt-1.5 h-1.5 w-1.5 rounded-full bg-primary shrink-0" />
                                            {rec}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        )}
                    </div>
                </>
            )}
        </div>
    );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Zap, Github, Loader2, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { initiateGithubLogin, signInWithEmail } from "@/lib/auth";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleManualLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError("Please enter both email and password.");
      return;
    }

    setIsLoading(true);
    setError(null);
    try {
      await signInWithEmail(email, password);
      navigate("/dashboard");
    } catch (err: any) {
      console.error("Login failed:", err);
      setError(err.response?.data?.detail || "Invalid email or password. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleGithubLogin = async () => {
    setIsLoading(true);
    try {
      await initiateGithubLogin();
    } catch (error) {
      console.error("Failed to initiate GitHub login:", error);
      setIsLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-background px-4">
      <div className="w-full max-w-sm">
        <div className="mb-8 text-center">
          <Link to="/" className="inline-flex items-center gap-2">
            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
              <Zap className="h-4 w-4 text-primary-foreground" />
            </div>
            <span className="text-lg font-semibold">DevIntel AI</span>
          </Link>
          <h1 className="mt-6 text-xl font-semibold">Welcome back</h1>
          <p className="mt-1 text-sm text-muted-foreground">Sign in to your account</p>
        </div>

        <form onSubmit={handleManualLogin} className="space-y-4">
          <Button
            type="button"
            variant="outline"
            className="w-full gap-2"
            onClick={handleGithubLogin}
            disabled={isLoading}
          >
            {isLoading ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Github className="h-4 w-4" />
            )}
            {isLoading ? "Redirecting to GitHub..." : "Continue with GitHub"}
          </Button>

          <div className="flex items-center gap-3">
            <div className="h-px flex-1 bg-border" />
            <span className="text-xs text-muted-foreground">or</span>
            <div className="h-px flex-1 bg-border" />
          </div>

          {error && (
            <Alert variant="destructive" className="py-2">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription className="text-xs">{error}</AlertDescription>
            </Alert>
          )}

          <div className="space-y-3">
            <div>
              <label className="text-sm font-medium text-foreground">Email</label>
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="you@company.com"
                className="mt-1.5 h-9 w-full rounded-md border border-input bg-accent px-3 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
                disabled={isLoading}
              />
            </div>
            <div>
              <label className="text-sm font-medium text-foreground">Password</label>
              <input
                type="password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="mt-1.5 h-9 w-full rounded-md border border-input bg-accent px-3 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
                disabled={isLoading}
              />
            </div>
          </div>

          <Button type="submit" className="w-full" disabled={isLoading}>
            {isLoading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Signing in...
              </>
            ) : (
              "Sign In"
            )}
          </Button>

          <p className="text-center text-sm text-muted-foreground">
            Don't have an account?{" "}
            <Link to="/signup" className="text-primary hover:underline">Sign up</Link>
          </p>
        </form>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { StatusBadge } from "@/components/shared/StatusBadge";
import { DiffViewer } from "@/components/shared/DiffViewer";
import { Button } from "@/components/ui/button";
import {
  GitPullRequest, Plus, Minus, ChevronRight, Check,
  MessageSquare, Loader2, Github, ChevronDown, GitMerge, Code2
} from "lucide-react";
import { apiClient } from "@/lib/api-client";
import { toast } from "sonner";
import type { Repository } from "@/lib/types";

interface PRDisplay {
  id: string;
  title: string;
  author: string;
  authorAvatar: string;
  status: 'open' | 'merged' | 'closed';
  createdAt: string;
  repository: string;
  additions: number;
  deletions: number;
  number: number;
  html_url: string;
  aiSummary?: string;
  suggestedChanges?: string[];
}

interface PullRequestResponse {
  id: number;
  number: number;
  title: string;
  html_url: string;
  state: 'open' | 'closed';
  merged_at: string | null;
  created_at: string;
  additions: number;
  deletions: number;
  user: { login: string; avatar_url: string };
  base: { repo: { full_name: string } };
}

interface PullRequestListResponse {
  pulls: PullRequestResponse[];
  repository_id: string;
}

type ActiveTab = 'overview' | 'diff';

const prStatusVariant = (s: string) =>
  s === "open" ? "primary" : s === "merged" ? "success" : "default";

function timeAgo(dateStr: string): string {
  const date = new Date(dateStr);
  const diffMs = Date.now() - date.getTime();
  const diffHours = Math.floor(diffMs / 3_600_000);
  if (diffHours < 1) return 'just now';
  if (diffHours < 24) return `${diffHours}h ago`;
  return `${Math.floor(diffHours / 24)}d ago`;
}

export default function PullRequestsPage() {
  const [repos, setRepos] = useState<Repository[]>([]);
  const [selectedRepo, setSelectedRepo] = useState<Repository | null>(null);
  const [pullRequests, setPullRequests] = useState<PRDisplay[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingPRs, setLoadingPRs] = useState(false);
  const [selected, setSelected] = useState<PRDisplay | null>(null);
  const [reviewing, setReviewing] = useState(false);
  const [stateFilter, setStateFilter] = useState<'open' | 'closed' | 'all'>('open');
  const [repoDropdownOpen, setRepoDropdownOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<ActiveTab>('overview');
  const [diff, setDiff] = useState<string | null>(null);
  const [loadingDiff, setLoadingDiff] = useState(false);

  useEffect(() => {
    async function fetchRepos() {
      try {
        const repoData = await apiClient.get<{ repositories: Repository[]; total: number }>('/api/v1/repos');
        const repoList = repoData.repositories || [];
        setRepos(repoList);
        if (repoList.length > 0) setSelectedRepo(repoList[0]);
      } catch (err) {
        console.error('Failed to fetch repositories:', err);
      } finally {
        setLoading(false);
      }
    }
    fetchRepos();
  }, []);

  useEffect(() => {
    if (!selectedRepo) return;
    fetchPRsForRepo(selectedRepo, stateFilter);
  }, [selectedRepo, stateFilter]);

  // Fetch diff when tab switches to diff
  useEffect(() => {
    if (activeTab === 'diff' && selected && selectedRepo && diff === null && !loadingDiff) {
      fetchDiff(selected, selectedRepo);
    }
  }, [activeTab, selected, selectedRepo]);

  const fetchPRsForRepo = async (repo: Repository, state: string) => {
    setLoadingPRs(true);
    setPullRequests([]);
    setSelected(null);
    setDiff(null);
    setActiveTab('overview');
    try {
      const data = await apiClient.get<PullRequestListResponse>(
        `/api/v1/repos/${repo.id}/pulls?state=${state}&per_page=30`
      );
      const prs: PRDisplay[] = (data.pulls || []).map((pr): PRDisplay => ({
        id: String(pr.id),
        title: pr.title,
        author: pr.user?.login || 'Unknown',
        authorAvatar: pr.user?.avatar_url || '',
        status: pr.merged_at ? 'merged' : pr.state,
        createdAt: timeAgo(pr.created_at),
        repository: pr.base?.repo?.full_name || repo.full_name,
        additions: pr.additions || 0,
        deletions: pr.deletions || 0,
        number: pr.number,
        html_url: pr.html_url,
      }));
      setPullRequests(prs);
    } catch (err: any) {
      toast.error(err.message || 'Failed to fetch pull requests');
    } finally {
      setLoadingPRs(false);
    }
  };

  const fetchDiff = async (pr: PRDisplay, repo: Repository) => {
    setLoadingDiff(true);
    try {
      const data = await apiClient.get<{ diff: string }>(`/api/v1/repos/${repo.id}/pulls/${pr.number}/diff`);
      setDiff(data.diff || '');
    } catch {
      toast.error('Failed to load diff from GitHub');
      setDiff('');
    } finally {
      setLoadingDiff(false);
    }
  };

  const handleSelectPR = (pr: PRDisplay) => {
    setSelected(pr);
    setDiff(null);
    setActiveTab('overview');
  };

  const handleAIReview = async (pr: PRDisplay) => {
    if (!pr || reviewing || !selectedRepo) return;
    setReviewing(true);
    try {
      const review = await apiClient.post<{
        summary: string;
        potential_issues: string[];
        refactoring_suggestions: string[];
        security_warnings: string[];
        performance_notes: string[];
      }>('/api/v1/pr-review', {
        repository_id: selectedRepo.id,
        pr_title: pr.title,
        pr_description: '',
        pr_number: pr.number,
        pull_request_diff: '',
      });

      const suggestedChanges = [
        ...review.potential_issues,
        ...review.refactoring_suggestions,
        ...review.security_warnings,
        ...review.performance_notes,
      ].filter(Boolean);

      const updatedPR = { ...pr, aiSummary: review.summary, suggestedChanges };
      setPullRequests(prev => prev.map(p => p.id === pr.id ? updatedPR : p));
      setSelected(updatedPR);
      toast.success('AI review complete');
    } catch (err: any) {
      toast.error(err.message || 'AI review failed');
    } finally {
      setReviewing(false);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-semibold">Pull Requests</h1>
        <p className="mt-1 text-sm text-muted-foreground">AI-powered code reviews with real diff preview</p>
      </div>

      {/* Controls */}
      {!loading && repos.length > 0 && (
        <div className="flex flex-wrap items-center gap-3">
          <div className="relative">
            <button
              onClick={() => setRepoDropdownOpen(v => !v)}
              className="flex items-center gap-2 h-9 rounded-md border border-input bg-accent px-3 text-sm outline-none hover:border-primary transition-colors"
            >
              <Github className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="max-w-[200px] truncate text-foreground">
                {selectedRepo ? selectedRepo.full_name : "Select repository"}
              </span>
              <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform shrink-0 ${repoDropdownOpen ? "rotate-180" : ""}`} />
            </button>
            {repoDropdownOpen && (
              <div className="absolute top-full mt-1 left-0 z-50 w-64 rounded-lg border border-border bg-card shadow-lg overflow-hidden animate-slide-up">
                {repos.map(r => (
                  <button
                    key={r.id}
                    onClick={() => { setSelectedRepo(r); setRepoDropdownOpen(false); }}
                    className="w-full flex items-center gap-2 px-3 py-2 text-sm text-left hover:bg-accent transition-colors"
                  >
                    <span className="flex-1 truncate text-card-foreground">{r.full_name}</span>
                    {selectedRepo?.id === r.id && <Check className="h-3.5 w-3.5 text-primary shrink-0" />}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div className="flex rounded-md border border-border overflow-hidden text-sm">
            {(['open', 'closed', 'all'] as const).map(s => (
              <button
                key={s}
                onClick={() => setStateFilter(s)}
                className={`px-3 py-1.5 capitalize transition-colors ${stateFilter === s
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-accent text-muted-foreground hover:text-foreground'
                  }`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      )}

      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      ) : repos.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 rounded-xl border border-dashed border-border">
          <GitPullRequest className="h-10 w-10 text-muted-foreground" />
          <p className="mt-3 text-sm font-medium">No repositories connected</p>
          <p className="mt-1 text-xs text-muted-foreground">Connect a repository first to view pull requests.</p>
        </div>
      ) : (
        <div className="grid gap-6 lg:grid-cols-5">
          {/* PR List */}
          <div className="lg:col-span-2 space-y-2">
            {loadingPRs ? (
              <div className="flex items-center justify-center py-12">
                <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
              </div>
            ) : pullRequests.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 rounded-xl border border-dashed border-border">
                <GitPullRequest className="h-8 w-8 text-muted-foreground" />
                <p className="mt-2 text-sm text-muted-foreground">No {stateFilter === 'all' ? '' : stateFilter} pull requests</p>
              </div>
            ) : (
              pullRequests.map((pr) => (
                <button
                  key={pr.id}
                  onClick={() => handleSelectPR(pr)}
                  className={`w-full rounded-xl border p-4 text-left transition-colors ${selected?.id === pr.id
                    ? "border-primary bg-primary/5"
                    : "border-border bg-card hover:border-primary/30"
                    }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex items-start gap-2 min-w-0">
                      {pr.authorAvatar ? (
                        <img src={pr.authorAvatar} alt={pr.author} className="mt-0.5 h-5 w-5 rounded-full shrink-0" />
                      ) : (
                        <GitPullRequest className="mt-0.5 h-4 w-4 text-muted-foreground shrink-0" />
                      )}
                      <div className="min-w-0">
                        <p className="text-sm font-medium text-card-foreground truncate">#{pr.number} {pr.title}</p>
                        <p className="mt-0.5 text-xs text-muted-foreground">{pr.author} · {pr.createdAt}</p>
                      </div>
                    </div>
                    <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
                  </div>
                  <div className="mt-2 flex items-center gap-3">
                    <StatusBadge status={pr.status} variant={prStatusVariant(pr.status)} />
                    <span className="flex items-center gap-1 text-xs text-green-500"><Plus className="h-3 w-3" />{pr.additions}</span>
                    <span className="flex items-center gap-1 text-xs text-red-500"><Minus className="h-3 w-3" />{pr.deletions}</span>
                  </div>
                </button>
              ))
            )}
          </div>

          {/* PR Detail */}
          <div className="lg:col-span-3">
            {selected ? (
              <div className="rounded-xl border border-border bg-card overflow-hidden">
                {/* PR header */}
                <div className="border-b border-border p-5">
                  <div className="flex items-start gap-3">
                    {selected.authorAvatar && (
                      <img src={selected.authorAvatar} alt={selected.author} className="h-8 w-8 rounded-full shrink-0 mt-0.5" />
                    )}
                    <div className="flex-1 min-w-0">
                      <h2 className="text-base font-semibold text-card-foreground">#{selected.number} {selected.title}</h2>
                      <p className="mt-0.5 text-xs text-muted-foreground">
                        by {selected.author} · {selected.createdAt} · {selected.repository}
                      </p>
                      <div className="mt-2 flex items-center gap-3">
                        <StatusBadge status={selected.status} variant={prStatusVariant(selected.status)} />
                        <span className="text-xs text-green-500">+{selected.additions}</span>
                        <span className="text-xs text-red-500">-{selected.deletions}</span>
                      </div>
                    </div>
                    {selected.html_url && (
                      <a href={selected.html_url} target="_blank" rel="noopener noreferrer"
                        className="shrink-0 flex items-center gap-1 rounded-md border border-border px-2 py-1 text-xs text-muted-foreground hover:bg-accent transition-colors">
                        <Github className="h-3 w-3" /> GitHub
                      </a>
                    )}
                  </div>

                  {/* Tab bar */}
                  <div className="mt-4 flex gap-1">
                    <button
                      onClick={() => setActiveTab('overview')}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeTab === 'overview' ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-accent'}`}
                    >
                      <MessageSquare className="h-3.5 w-3.5" />
                      Overview
                    </button>
                    <button
                      onClick={() => setActiveTab('diff')}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${activeTab === 'diff' ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-accent'}`}
                    >
                      <Code2 className="h-3.5 w-3.5" />
                      Diff
                    </button>
                  </div>
                </div>

                {/* Tab content */}
                <div className="p-5">
                  {activeTab === 'overview' ? (
                    <div className="space-y-5">
                      {selected.aiSummary ? (
                        <div className="rounded-lg border border-primary/20 bg-primary/5 p-4">
                          <p className="text-xs font-medium text-primary mb-2">AI Review Summary</p>
                          <p className="text-sm text-card-foreground leading-relaxed">{selected.aiSummary}</p>
                        </div>
                      ) : (
                        <div className="rounded-lg border border-border bg-muted p-4 text-center">
                          <GitMerge className="h-6 w-6 mx-auto text-muted-foreground mb-2" />
                          <p className="text-sm text-muted-foreground">Run AI Review to analyze this pull request</p>
                        </div>
                      )}

                      {selected.suggestedChanges && selected.suggestedChanges.length > 0 && (
                        <div>
                          <p className="text-sm font-medium text-card-foreground mb-3">Suggested Changes</p>
                          <ul className="space-y-2">
                            {selected.suggestedChanges.map((change, i) => (
                              <li key={i} className="flex items-start gap-2 rounded-lg border border-border bg-muted p-3 text-sm text-card-foreground">
                                <MessageSquare className="mt-0.5 h-4 w-4 text-primary shrink-0" />
                                {change}
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}

                      <div className="flex gap-3 pt-1">
                        <Button className="gap-2" onClick={() => handleAIReview(selected)} disabled={reviewing}>
                          {reviewing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                          {reviewing ? 'Reviewing...' : 'AI Review'}
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div>
                      {loadingDiff ? (
                        <div className="flex items-center justify-center py-12">
                          <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
                          <span className="ml-2 text-sm text-muted-foreground">Loading diff from GitHub...</span>
                        </div>
                      ) : (
                        <DiffViewer diff={diff || ''} maxHeightPx={520} />
                      )}
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="flex h-64 items-center justify-center rounded-xl border border-dashed border-border">
                <p className="text-sm text-muted-foreground">Select a pull request to view details</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Plus, Search, RefreshCw, Trash2, Github, Loader2, AlertCircle, Check, Wifi } from "lucide-react";
import { StatusBadge } from "@/components/shared/StatusBadge";
import { Button } from "@/components/ui/button";
import { apiClient } from "@/lib/api-client";
import { toast } from "sonner";
import type { Repository, GitHubRepo } from "@/lib/types";
import { useIndexingProgress } from "@/hooks/useIndexingProgress";

const statusVariant = (repo: Repository) => {
  if (repo.indexing_error) return "error";
  if (repo.indexed_status) return "success";
  if (repo.indexing_progress > 0 && repo.indexing_progress < 100) return "warning";
  return "default";
};

const statusLabel = (repo: Repository, liveProgress?: number) => {
  if (repo.indexing_error) return "Failed";
  if (repo.indexed_status) return "Indexed";
  const p = liveProgress ?? repo.indexing_progress;
  if (p > 0 && p < 100) return `Indexing ${p}%`;
  return "Not Indexed";
};

/** Sub-component: shows live WS progress for a repo being indexed */
function RepoProgressRow({
  repo,
  onComplete,
}: {
  repo: Repository;
  onComplete: () => void;
}) {
  const isIndexing =
    !repo.indexed_status &&
    repo.indexing_progress > 0 &&
    repo.indexing_progress < 100;

  const { progress, connected } = useIndexingProgress({
    repoId: repo.id,
    enabled: isIndexing,
    onComplete,
  });

  const liveProgress = isIndexing && progress > 0 ? progress : repo.indexing_progress;
  const displayVariant = repo.indexing_error
    ? "error"
    : repo.indexed_status
      ? "success"
      : liveProgress > 0 && liveProgress < 100
        ? "warning"
        : "default";

  return (
    <div className="flex items-center gap-2">
      <StatusBadge
        status={statusLabel(repo, isIndexing ? liveProgress : undefined)}
        variant={displayVariant}
      />
      {isIndexing && connected && (
        <Wifi
          className="h-3 w-3 text-emerald-400 animate-pulse"
          aria-label="Live WebSocket progress"
        />
      )}
      {repo.indexing_error && (
        <div className="group relative">
          <AlertCircle className="h-4 w-4 text-destructive cursor-help" />
          <div className="absolute bottom-full left-1/2 mb-2 hidden -translate-x-1/2 rounded bg-destructive px-2 py-1 text-[10px] text-destructive-foreground group-hover:block whitespace-nowrap z-50">
            {repo.indexing_error}
          </div>
        </div>
      )}
    </div>
  );
}

export default function RepositoriesPage() {
  const [repos, setRepos] = useState<Repository[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [githubRepos, setGithubRepos] = useState<GitHubRepo[]>([]);
  const [loadingGH, setLoadingGH] = useState(false);
  const [repoUrl, setRepoUrl] = useState("");
  const [connecting, setConnecting] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [indexingId, setIndexingId] = useState<string | null>(null);

  const fetchRepos = async () => {
    setLoading(true);
    try {
      const data = await apiClient.get<{ repositories: Repository[]; total: number }>('/api/v1/repos');
      setRepos(data.repositories || []);
    } catch (err) {
      console.error('Failed to fetch repos:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchRepos(); }, []);

  const fetchGithubRepos = async () => {
    setLoadingGH(true);
    try {
      const data = await apiClient.get<{ repositories: GitHubRepo[] }>('/api/v1/repos/github?per_page=50');
      setGithubRepos(Array.isArray(data.repositories) ? data.repositories : []);
    } catch (err) {
      console.error('Failed to fetch GitHub repos:', err);
      toast.error('Failed to fetch your GitHub repositories');
    } finally {
      setLoadingGH(false);
    }
  };

  const handleOpenModal = () => {
    setShowModal(true);
    fetchGithubRepos();
  };

  const connectRepo = async (ghRepo: GitHubRepo) => {
    setConnecting(true);
    try {
      await apiClient.post('/api/v1/repos', {
        repo_name: ghRepo.repo_name,
        full_name: ghRepo.full_name,
        url: ghRepo.url,
        description: ghRepo.description || '',
        stars: ghRepo.stars || 0,
        language: ghRepo.language || null,
      });
      toast.success(`Connected ${ghRepo.full_name}`);
      setShowModal(false);
      setRepoUrl("");
      await fetchRepos();
    } catch (err: any) {
      toast.error(err.message || 'Failed to connect repository');
    } finally {
      setConnecting(false);
    }
  };

  const handleConnectByUrl = () => {
    if (!repoUrl.trim()) return;
    // Extract owner/repo from URL
    const match = repoUrl.match(/github\.com\/([^/]+\/[^/]+)/);
    if (match) {
      const fullName = match[1].replace(/\.git$/, '');
      const name = fullName.split('/').pop() || fullName;
      connectRepo({
        repo_name: name,
        full_name: fullName,
        url: repoUrl.trim(),
        description: null,
        stars: 0,
        language: null,
        private: false,
      } as GitHubRepo);
    } else {
      toast.error('Invalid GitHub URL. Expected: https://github.com/owner/repo');
    }
  };

  const handleDelete = async (id: string, name: string) => {
    if (!confirm(`Delete repository "${name}"? This cannot be undone.`)) return;
    setDeletingId(id);
    try {
      await apiClient.delete(`/api/v1/repos/${id}`);
      toast.success(`Deleted ${name}`);
      setRepos(prev => prev.filter(r => r.id !== id));
    } catch (err: any) {
      toast.error(err.message || 'Failed to delete repository');
    } finally {
      setDeletingId(null);
    }
  };

  const handleIndex = async (id: string) => {
    setIndexingId(id);
    try {
      await apiClient.post('/api/v1/repos/index', { repository_id: id });
      toast.success('Indexing started');
      await fetchRepos();
    } catch (err: any) {
      toast.error(err.message || 'Failed to start indexing');
    } finally {
      setIndexingId(null);
    }
  };

  const filtered = repos.filter((r) => (r.full_name || r.repo_name).toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-semibold">My Repositories</h1>
          <p className="mt-1 text-sm text-muted-foreground">Manage and index your GitHub repositories</p>
        </div>
        <Button className="gap-2" onClick={handleOpenModal}>
          <Github className="h-4 w-4" /> Connect Repository
        </Button>
      </div>

      <div className="relative max-w-sm">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <input
          type="text"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search repositories..."
          className="h-9 w-full rounded-md border border-input bg-accent pl-9 pr-4 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
        />
      </div>

      <div className="overflow-hidden rounded-xl border border-border">
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
          </div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16">
            <Github className="h-10 w-10 text-muted-foreground" />
            <p className="mt-3 text-sm text-muted-foreground">
              {repos.length === 0 ? "No repositories connected yet" : "No matching repositories"}
            </p>
            {repos.length === 0 && (
              <Button size="sm" className="mt-3 gap-2" onClick={handleOpenModal}>
                <Plus className="h-3 w-3" /> Connect your first repo
              </Button>
            )}
          </div>
        ) : (
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border bg-muted">
                <th className="px-4 py-3 text-left font-medium text-muted-foreground">Repository</th>
                <th className="px-4 py-3 text-left font-medium text-muted-foreground">Status</th>
                <th className="hidden px-4 py-3 text-left font-medium text-muted-foreground sm:table-cell">Language</th>
                <th className="px-4 py-3 text-right font-medium text-muted-foreground">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((repo) => (
                <tr key={repo.id} className="border-b border-border last:border-0 hover:bg-accent/50 transition-colors">
                  <td className="px-4 py-3">
                    <div>
                      <p className="font-medium text-foreground">{repo.repo_name}</p>
                      <p className="text-xs text-muted-foreground">{repo.full_name}</p>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <RepoProgressRow repo={repo} onComplete={fetchRepos} />
                  </td>
                  <td className="hidden px-4 py-3 text-muted-foreground sm:table-cell">{repo.language || '—'}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-1">
                      <button
                        onClick={() => handleIndex(repo.id)}
                        disabled={indexingId === repo.id}
                        className="rounded p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground transition-colors disabled:opacity-50"
                        title="Re-index"
                      >
                        {indexingId === repo.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
                      </button>
                      <button
                        onClick={() => handleDelete(repo.id, repo.full_name)}
                        disabled={deletingId === repo.id}
                        className="rounded p-1.5 text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-colors disabled:opacity-50"
                        title="Delete"
                      >
                        {deletingId === repo.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Connect Repository Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm">
          <div className="w-full max-w-lg rounded-xl border border-border bg-card p-6 shadow-lg animate-slide-up max-h-[80vh] flex flex-col">
            <h2 className="text-lg font-semibold text-card-foreground">Connect GitHub Repository</h2>

            {/* URL input */}
            <div className="mt-4">
              <label className="text-sm font-medium text-foreground">Repository URL</label>
              <div className="flex gap-2 mt-1.5">
                <input
                  type="text"
                  value={repoUrl}
                  onChange={(e) => setRepoUrl(e.target.value)}
                  placeholder="https://github.com/owner/repo"
                  className="h-9 flex-1 rounded-md border border-input bg-accent px-3 text-sm text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
                />
                <Button size="sm" onClick={handleConnectByUrl} disabled={connecting || !repoUrl.trim()}>
                  {connecting ? <Loader2 className="h-4 w-4 animate-spin" /> : 'Connect'}
                </Button>
              </div>
            </div>

            {/* Divider */}
            <div className="flex items-center gap-3 my-4">
              <div className="h-px flex-1 bg-border" />
              <span className="text-xs text-muted-foreground">or select from your GitHub</span>
              <div className="h-px flex-1 bg-border" />
            </div>

            {/* GitHub repos list */}
            <div className="flex-1 overflow-auto space-y-1 min-h-0">
              {loadingGH ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
                </div>
              ) : githubRepos.length === 0 ? (
                <p className="text-sm text-muted-foreground text-center py-4">No repositories found</p>
              ) : (
                githubRepos.map((ghRepo) => {
                  const alreadyConnected = repos.some(r => r.full_name === ghRepo.full_name);
                  return (
                    <button
                      key={ghRepo.full_name}
                      disabled={alreadyConnected || connecting}
                      onClick={() => connectRepo(ghRepo)}
                      className={`w-full flex items-center gap-3 rounded-lg p-3 text-left transition-colors ${alreadyConnected
                        ? 'opacity-50 cursor-not-allowed bg-accent/30'
                        : 'hover:bg-accent'
                        }`}
                    >
                      <Github className="h-4 w-4 text-muted-foreground shrink-0" />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-card-foreground truncate">{ghRepo.full_name}</p>
                        <p className="text-xs text-muted-foreground truncate">
                          {ghRepo.language || 'Unknown'} · {ghRepo.stars || 0} ★{ghRepo.private ? ' · Private' : ''}
                        </p>
                      </div>
                      {alreadyConnected && (
                        <span className="text-xs text-success flex items-center gap-1"><Check className="h-3 w-3" /> Added</span>
                      )}
                    </button>
                  );
                })
              )}
            </div>

            <div className="mt-4 flex justify-end">
              <Button variant="outline" onClick={() => { setShowModal(false); setRepoUrl(""); }}>Close</Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

